INSERT INTO `site_content` (`id`,`key`,`value`,`updatedAt`,`updatedBy`) VALUES ('content-027', 'journal.stories', '[{"id":"story-hands-that-keep-the-fire","slug":"hands-that-keep-the-fire","slugVi":"nhung-ban-tay-giu-lua","slugEn":"hands-that-keep-the-fire","titleVi":"Nhung ban tay giu lua","titleEn":"Hands That Keep the Fire","summaryVi":"Cau chuyen ve nhung nguoi tho gom va nhip song cham trong xuong.","summaryEn":"A story about ceramic artisans and the quiet rhythm of the workshop.","contentVi":"<p>Moi san pham bat dau tu dat, lua va su kien nhan cua ban tay nguoi tho.</p>","contentEn":"<p>Every piece begins with clay, fire, and the patience of the maker.</p>","imageUrl":"https://images.uomarchive.com/seed/journal-hands.png","publishedAt":"2026-03-12","updatedAt":"2026-03-12","isVisible":true},{"id":"story-glaze-and-light","slug":"glaze-and-light","slugVi":"mau-men-va-anh-sang","slugEn":"glaze-and-light","titleVi":"Mau men va anh sang","titleEn":"Glaze and Light","summaryVi":"Cach men gom thay doi tinh te theo tung nguon sang trong nha.","summaryEn":"How ceramic glaze shifts gently with different sources of light.","contentVi":"<p>Men gom co the am hon, sau hon hoac diu hon tuy theo anh sang tu nhien va den trong nha.</p>","contentEn":"<p>Glaze can feel warmer, deeper, or softer depending on daylight and indoor lighting.</p>","imageUrl":"https://images.uomarchive.com/seed/journal-glaze.png","publishedAt":"2026-03-20","updatedAt":"2026-03-20","isVisible":true},{"id":"story-minimal-tea-ritual","slug":"minimal-tea-ritual","slugVi":"nghi-thuc-ban-tra-toi-gian","slugEn":"minimal-tea-ritual","titleVi":"Nghi thuc ban tra toi gian","titleEn":"A Minimal Tea Ritual","summaryVi":"Mot vai mon gom vua du de tao nen khoang lang yen trong ngay.","summaryEn":"A few thoughtful ceramic pieces can create a calm daily pause.","contentVi":"<p>Mot am tra, vai chiec chen va mot khoang trong la du cho mot nghi thuc nho.</p>","contentEn":"<p>A teapot, a few cups, and some empty space are enough for a small ritual.</p>","imageUrl":"https://images.uomarchive.com/seed/journal-tea.png","publishedAt":"2026-03-28","updatedAt":"2026-03-28","isVisible":true}]', NOW(3), 'admin-seed') ON DUPLICATE KEY UPDATE `value`=VALUES(`value`), `updatedAt`=NOW(3), `updatedBy`='admin-seed';
