INSERT INTO `site_content` (`id`,`key`,`value`,`updatedAt`,`updatedBy`) VALUES ('content-037', 'about.storyContent.en', 'ƯƠM. Archive is built from a love for clay, glaze, and handmade traces. We curate practical objects that invite slower, quieter living.', NOW(3), 'admin-seed') ON DUPLICATE KEY UPDATE `value`=VALUES(`value`), `updatedAt`=NOW(3), `updatedBy`='admin-seed';
