SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

-- Canonical UOM Archive production seed.
-- Image URLs are synchronized with backend/prisma/seed.ts and release/seed-assets/manifest.json.
-- This removes older seed rows that may still point to .jpg or stale generated assets.
DELETE FROM `_RelatedProducts` WHERE `A` LIKE 'prod-%' OR `B` LIKE 'prod-%';
DELETE FROM `banners` WHERE `id` IN ('banner-home-main','banner-new-collection') OR `imageUrl` LIKE 'https://images.uomarchive.com/seed/%';
DELETE FROM `products` WHERE `id` LIKE 'prod-%' OR `images` LIKE '%https://images.uomarchive.com/seed/%' OR `hoverImage` LIKE 'https://images.uomarchive.com/seed/%';
DELETE FROM `categories` WHERE `id` LIKE 'cat-%' OR `image` LIKE 'https://images.uomarchive.com/seed/%';
DELETE FROM `site_content` WHERE `id` LIKE 'content-%' OR `key` IN (
  'menu.shop.vi','menu.shop.en','menu.inquiry.vi','menu.inquiry.en','menu.shipping.vi','menu.shipping.en',
  'brand.name.vi','brand.name.en','brand.tagline.vi','brand.tagline.en','footer.text.vi','footer.text.en',
  'hero.title.vi','hero.title.en','hero.subtitle.vi','hero.subtitle.en','hero.image.vi','hero.image.en',
  'inquiry.button.vi','inquiry.button.en','site.title.vi','site.title.en','site.description.vi','site.description.en',
  'site.logoUrl','site.loadingText','journal.stories','search.trending.vi','search.trending.en',
  'about.heroTitle.vi','about.heroTitle.en','about.heroSubtitle.vi','about.heroSubtitle.en',
  'about.storyTitle.vi','about.storyTitle.en','about.storyContent.vi','about.storyContent.en','about.storyImage',
  'about.philosophyTitle.vi','about.philosophyTitle.en','about.philosophyDescription.vi','about.philosophyDescription.en',
  'about.philosophyContent.vi','about.philosophyContent.en','about.values.craft.title.vi','about.values.craft.title.en',
  'about.values.craft.description.vi','about.values.craft.description.en','about.values.sustainability.title.vi',
  'about.values.sustainability.title.en','about.values.sustainability.description.vi','about.values.sustainability.description.en',
  'about.values.essence.title.vi','about.values.essence.title.en','about.values.essence.description.vi','about.values.essence.description.en'
);
DELETE FROM `theme_settings` WHERE `id` = 'singleton';
DELETE FROM `social_settings` WHERE `id` = 'singleton';
DELETE FROM `site_settings` WHERE `id` = 'singleton' OR `key` = 'exchange_rate';
DELETE FROM `users` WHERE `id` IN ('manager-seed','admin-seed');

ON DUPLICATE KEY UPDATE `passwordHash`=VALUES(`passwordHash`), `fullName`=VALUES(`fullName`), `role`=VALUES(`role`), `isActive`=VALUES(`isActive`), `updatedAt`=NOW(3);

ON DUPLICATE KEY UPDATE `passwordHash`=VALUES(`passwordHash`), `fullName`=VALUES(`fullName`), `role`=VALUES(`role`), `isActive`=VALUES(`isActive`), `updatedBy`='admin-seed', `updatedAt`=NOW(3);







SET FOREIGN_KEY_CHECKS=1;
